INSERT INTO feature VALUES('corecursion','recursion','Guarded corecursion',NULL,'partial','notable',NULL,'A fixpoint into a coinductive datatype carries the guard as its evidence: the kernel walks its body once and admits it when each call stands under a constructor of that datatype, through the constructors, their thunks, abstractions, the branches of a case and the lets that hold no call, and conversion unfolds it once for each observation. The surface `[>]` still crosses as a partial fixpoint (#2742), and the sized guard is owed (#392).','kernel-term kernel-core','crates/kernel-core/tests/guard.rs','crate-tests','#392 #2742');
